{
  "a_sentences": [
    {
      "a_text": "La question litigieuse porte sur la violation du droit fédéral par la juridiction cantonale en octroyant à l'intimée une rente d'invalidité fondée sur un taux de 31 %, plus précisément sur la détermination du revenu d'invalide.",
      "b_propositions": ["P1", "P2"]
    },
    {
      "a_text": "Pour fixer le revenu d'invalide, il convient de se référer en premier lieu à la situation professionnelle concrète de la personne assurée.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Lorsque l'assurée n'exerce plus d'activité lucrative après l'atteinte à la santé, les salaires statistiques de l'enquête suisse sur la structure des salaires (ESS) peuvent être utilisés.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Il est généralement fait appel aux valeurs totales de la table TA1_tirage_skill_level pour le secteur privé.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Cette table s'applique notamment lorsque l'assurée ne peut plus exercer son activité habituelle et doit se tourner vers un nouveau domaine d'activité, l'ensemble du marché du travail lui étant ouvert.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La juridiction cantonale n'a pas violé le droit fédéral en déterminant le revenu d'invalide sur la base de la table TA1_tirage_skill_level.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme ainsi un taux d'invalidité de 31 % calculé à partir d'un revenu d'invalide de 49'660.55 francs.",
      "b_propositions": ["P8"]
    }
  ]
}
